'use client';

import { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import { motion } from 'framer-motion';
import {
  Dialog,
  DialogContent,
  DialogTrigger,
  DialogTitle,
} from '@/components/ui/dialog';
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from '@/components/ui/tooltip';
import { useResumeStore } from '@/store/useResumeStore';
import { Pencil } from 'lucide-react';
import { signOut } from 'next-auth/react';
import { useRouter } from 'next/navigation';
import { arrayMove } from '@dnd-kit/sortable';
import { DragEndEvent } from '@dnd-kit/core';
import { ResumeData } from '@/lib/server/dbActions';
import { useUserActions } from '@/hooks/useUserActions';
import { useS3Upload } from 'next-s3-upload';
import { DEFAULT_SECTION_ORDER } from '@/lib/resume';
import { toast } from 'sonner';
import { ProfileSidebar } from './ProfileSidebar';
import { ProfileContent } from './ProfileContent';
import { DeleteConfirmDialog, UnsavedChangesDialog } from './dialogs';

// ---------------------------------------------------------------------------
// Constants — hoisted outside the component so they are never reallocated
// ---------------------------------------------------------------------------

const TAB_DEFINITIONS: Record<string, { label: string; disabled: boolean }> = {
  work: { label: 'Work Experience', disabled: false },
  side_projects: { label: 'Side Projects', disabled: false },
  speaking: { label: 'Speaking', disabled: false },
  projects: { label: 'Projects', disabled: false },
  skills: { label: 'Skills', disabled: false },
  education: { label: 'Education', disabled: false },
  contact: { label: 'Contact', disabled: false },
  awards: { label: 'Awards', disabled: true },
  volunteering: { label: 'Volunteering', disabled: false },
  features: { label: 'Features', disabled: false },
  print: { label: 'Print', disabled: false },
};

type DeleteTarget =
  | { type: 'project'; id: string }
  | { type: 'sideProject'; id: string }
  | { type: 'speaking'; id: string }
  | { type: 'volunteering'; id: string }
  | { type: 'feature'; id: string }
  | { type: 'education'; id: string }
  | { type: 'work'; id: string }
  | { type: 'contact'; id: string };

const DELETE_DESCRIPTIONS: Record<DeleteTarget['type'], string> = {
  project:
    'This will permanently delete this project. This action cannot be undone.',
  sideProject:
    'This will permanently delete this side project. This action cannot be undone.',
  speaking:
    'This will permanently delete this speaking engagement. This action cannot be undone.',
  work: 'This will permanently delete this work experience. This action cannot be undone.',
  contact:
    'This will permanently delete this contact. This action cannot be undone.',
  volunteering:
    'This will permanently delete this volunteering entry. This action cannot be undone.',
  feature:
    'This will permanently delete this feature. This action cannot be undone.',
  education:
    'This will permanently delete this education entry. This action cannot be undone.',
};

// ---------------------------------------------------------------------------

export function EditProfileDialog({
  resume,
  username,
  picture,
}: {
  resume: ResumeData;
  username: string;
  picture?: string;
}) {
  const {
    uname,
    activeTab,
    setActiveTab,
    hasUnsavedChanges,
    setHasUnsavedChanges,
    initResume,
    isEditingTab,
  } = useResumeStore();

  useEffect(() => {
    initResume(resume, username);
  }, [resume, username, initResume]);

  const [open, setOpen] = useState(false);
  const [showMobileMenu, setShowMobileMenu] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [showUnsavedWarning, setShowUnsavedWarning] = useState(false);
  const [localPicture, setLocalPicture] = useState<string | undefined>(picture);
  const [isUploadingPicture, setIsUploadingPicture] = useState(false);
  const [pendingDelete, setPendingDelete] = useState<DeleteTarget | null>(null);
  const [showDeleteAccountWarning, setShowDeleteAccountWarning] =
    useState(false);
  const [isDeletingAccount, setIsDeletingAccount] = useState(false);

  const debounceTimerRef = useRef<NodeJS.Timeout | null>(null);
  const isInitialUsername = uname === username;

  const {
    saveResumeDataMutation,
    updateUsernameMutation,
    checkUsernameMutation,
  } = useUserActions();

  const isValidUname =
    /^[a-zA-Z0-9-]+$/.test(uname) &&
    uname.length > 0 &&
    ((isInitialUsername || checkUsernameMutation.data?.available) ?? false);

  // Username availability debounce — lives here only; GeneralTab renders the input
  useEffect(() => {
    if (!isInitialUsername && uname) {
      if (debounceTimerRef.current) clearTimeout(debounceTimerRef.current);
      debounceTimerRef.current = setTimeout(() => {
        checkUsernameMutation.mutateAsync(uname);
      }, 500);
    }
    return () => {
      if (debounceTimerRef.current) clearTimeout(debounceTimerRef.current);
    };
  }, [uname, isInitialUsername, checkUsernameMutation.mutateAsync]);

  // Section order — normalise legacy ids on first load only
  const [sectionOrder, setSectionOrder] = useState<string[]>(
    () => resume.sectionOrder || DEFAULT_SECTION_ORDER,
  );

  // Years list — stable; only computed once
  const years = useMemo(() => {
    const current = new Date().getFullYear();
    // Start from current year and go down to 1980
    return Array.from({ length: current - 1980 + 1 }, (_, i) => current - i);
  }, []);

  const { uploadToS3 } = useS3Upload();
  const router = useRouter();

  // ---------------------------------------------------------------------------
  // Stable delete setters — prevent inline arrow re-creation on every render
  // ---------------------------------------------------------------------------
  const makeDeleteSetter = useCallback(
    (type: DeleteTarget['type']) => (id: string) =>
      setPendingDelete({ type, id }),
    [],
  );

  const setDeleteProject = useMemo(
    () => makeDeleteSetter('project'),
    [makeDeleteSetter],
  );
  const setDeleteSideProject = useMemo(
    () => makeDeleteSetter('sideProject'),
    [makeDeleteSetter],
  );
  const setDeleteSpeaking = useMemo(
    () => makeDeleteSetter('speaking'),
    [makeDeleteSetter],
  );
  const setDeleteWork = useMemo(
    () => makeDeleteSetter('work'),
    [makeDeleteSetter],
  );
  const setDeleteEducation = useMemo(
    () => makeDeleteSetter('education'),
    [makeDeleteSetter],
  );
  const setDeleteVolunteering = useMemo(
    () => makeDeleteSetter('volunteering'),
    [makeDeleteSetter],
  );
  const setDeleteFeature = useMemo(
    () => makeDeleteSetter('feature'),
    [makeDeleteSetter],
  );
  const setDeleteContact = useMemo(
    () => makeDeleteSetter('contact'),
    [makeDeleteSetter],
  );

  // ---------------------------------------------------------------------------
  // Delete handlers — stable; reads store at call-time so no stale closure
  // ---------------------------------------------------------------------------
  const DELETE_HANDLERS = useMemo<
    Record<DeleteTarget['type'], (id: string) => void>
  >(
    () => ({
      project: (id) => {
        const s = useResumeStore.getState();
        s.updateResume({
          projects: s.resume?.projects?.filter((p: any) => p.id !== id),
        });
      },
      sideProject: (id) => {
        const s = useResumeStore.getState();
        s.updateResume({
          sideProjects: s.resume?.sideProjects?.filter((p: any) => p.id !== id),
        });
      },
      speaking: (id) => {
        const s = useResumeStore.getState();
        s.updateResume({
          speaking: s.resume?.speaking?.filter((p: any) => p.id !== id),
        });
      },
      work: (id) => {
        const s = useResumeStore.getState();
        s.updateResume({
          workExperience: s.resume?.workExperience?.filter(
            (p: any) => p.id !== id,
          ),
        });
      },
      contact: (id) => {
        const s = useResumeStore.getState();
        s.updateResume({
          contacts: s.resume?.contacts?.filter((p: any) => p.id !== id),
        });
      },
      volunteering: (id) => {
        const s = useResumeStore.getState();
        s.updateResume({
          volunteering: s.resume?.volunteering?.filter((p: any) => p.id !== id),
        });
      },
      feature: (id) => {
        const s = useResumeStore.getState();
        s.updateResume({
          features: s.resume?.features?.filter((p: any) => p.id !== id),
        });
      },
      education: (id) => {
        const s = useResumeStore.getState();
        s.updateResume({
          education: s.resume?.education?.filter((p: any) => p.id !== id),
        });
      },
    }),
    [],
  );

  // ---------------------------------------------------------------------------
  // Avatar
  // ---------------------------------------------------------------------------
  const handleAvatarUpload = useCallback(
    async (file: File) => {
      if (!file.type.startsWith('image/')) {
        toast.error('Please select an image file');
        return;
      }
      if (file.size > 5 * 1024 * 1024) {
        toast.error('Image must be under 5MB');
        return;
      }
      const blobUrl = URL.createObjectURL(file);
      setLocalPicture(blobUrl);
      setIsUploadingPicture(true);
      try {
        const { url } = await uploadToS3(file, {
          endpoint: { request: { url: '/api/s3-upload' } },
        });
        const res = await fetch('/api/user/avatar', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ url }),
        });
        if (!res.ok) throw new Error('Failed to save avatar');
        setLocalPicture(url);
        URL.revokeObjectURL(blobUrl);
        toast.success('Profile picture updated');
      } catch {
        setLocalPicture(picture);
        URL.revokeObjectURL(blobUrl);
        toast.error('Failed to upload image');
      } finally {
        setIsUploadingPicture(false);
      }
    },
    [uploadToS3, picture],
  );

  const handleAvatarRemove = useCallback(async () => {
    setIsUploadingPicture(true);
    setLocalPicture(undefined);
    try {
      const res = await fetch('/api/user/avatar', { method: 'DELETE' });
      if (!res.ok) throw new Error('Failed to remove');
      toast.success('Profile picture removed');
    } catch {
      setLocalPicture(picture);
      toast.error('Failed to remove image');
    } finally {
      setIsUploadingPicture(false);
    }
  }, [picture]);

  // Stable wrapper: GeneralTab passes a ChangeEvent; we extract the File
  const handlePictureUpload = useCallback(
    (e: React.ChangeEvent<HTMLInputElement>) => {
      const file = e.target.files?.[0];
      if (file) return handleAvatarUpload(file);
      return Promise.resolve();
    },
    [handleAvatarUpload],
  );

  // ---------------------------------------------------------------------------
  // Account deletion
  // ---------------------------------------------------------------------------
  const handleDeleteAccount = useCallback(async () => {
    setIsDeletingAccount(true);
    try {
      const res = await fetch('/api/user', { method: 'DELETE' });
      if (!res.ok) throw new Error('Failed to delete account');
      toast.success('Account deleted successfully');
      setOpen(false);
      await signOut({ callbackUrl: '/' });
      window.location.href = '/';
    } catch (error) {
      toast.error('Failed to delete account');
      console.error(error);
    } finally {
      setIsDeletingAccount(false);
      setShowDeleteAccountWarning(false);
    }
  }, []);

  // ---------------------------------------------------------------------------
  // Global save
  // ---------------------------------------------------------------------------
  const handleGlobalSave = useCallback(async () => {
    setIsSaving(true);
    try {
      if (uname !== username) {
        const unameRes = await updateUsernameMutation.mutateAsync(uname);
        if (!unameRes) {
          toast.error('Username update failed. It might be taken.');
          setIsSaving(false);
          return;
        }
      }
      const newResumeData = useResumeStore.getState().resume;
      if (newResumeData) {
        await saveResumeDataMutation.mutateAsync(newResumeData);
        setHasUnsavedChanges(false);
        toast.success('Profile updated successfully');
        setOpen(false);
        if (uname !== username) {
          router.push(`/${uname}`);
        }
      }
    } catch {
      toast.error('Failed to update profile');
    } finally {
      setIsSaving(false);
    }
  }, [
    uname,
    username,
    updateUsernameMutation,
    saveResumeDataMutation,
    setHasUnsavedChanges,
    router,
  ]);

  const handleDragEnd = useCallback(
    (event: DragEndEvent) => {
      const { active, over } = event;
      if (over && active.id !== over.id) {
        const oldIndex = sectionOrder.indexOf(active.id as string);
        const newIndex = sectionOrder.indexOf(over.id as string);
        const newOrder = arrayMove(sectionOrder, oldIndex, newIndex);

        setSectionOrder(newOrder);
        useResumeStore.getState().updateResume({ sectionOrder: newOrder });
        setHasUnsavedChanges(true);
      }
    },
    [sectionOrder, setHasUnsavedChanges],
  );

  // ---------------------------------------------------------------------------
  // Render
  // ---------------------------------------------------------------------------
  return (
    <>
      <Dialog
        open={open}
        onOpenChange={(val) => {
          if (!val && hasUnsavedChanges) {
            setShowUnsavedWarning(true);
            return;
          }
          setOpen(val);
        }}
      >
        <TooltipProvider delayDuration={0}>
          <Tooltip>
            <DialogTrigger asChild>
              <TooltipTrigger asChild>
                <motion.button
                  whileTap={{ scale: 0.9 }}
                  aria-label="Edit Profile"
                  style={{
                    position: 'fixed',
                    bottom: '24px',
                    left: '80px',
                    zIndex: 50,
                  }}
                  className="flex size-[48px] items-center justify-center rounded-full border border-gray-200 bg-white shadow-sm outline-none transition-colors"
                >
                  <Pencil
                    className="h-[18px] w-[18px] text-[#111]"
                    strokeWidth={1.5}
                  />
                </motion.button>
              </TooltipTrigger>
            </DialogTrigger>
            <TooltipContent
              side="top"
              sideOffset={12}
              className="flex items-center gap-1.5 rounded-lg border-none bg-[#111] px-3 py-1.5 text-[13px] font-medium text-white shadow-md"
            >
              <span>Edit profile</span>
            </TooltipContent>
          </Tooltip>
        </TooltipProvider>

        <DialogContent className="flex h-[85vh] max-w-5xl flex-col gap-0 overflow-hidden overscroll-contain bg-white p-0 sm:flex-row">
          <DialogTitle className="sr-only">Edit Profile</DialogTitle>

          {/* Sidebar */}
          <ProfileSidebar
            activeTab={activeTab}
            setActiveTab={setActiveTab}
            setShowMobileMenu={setShowMobileMenu}
            showMobileMenu={showMobileMenu}
            sectionOrder={sectionOrder}
            setSectionOrder={setSectionOrder}
            tabDefinitions={TAB_DEFINITIONS}
            onDragEnd={handleDragEnd}
          />

          {/* Content Area */}
          <ProfileContent
            activeTab={activeTab}
            showMobileMenu={showMobileMenu}
            setShowMobileMenu={setShowMobileMenu}
            username={username}
            localPicture={localPicture}
            isUploadingPicture={isUploadingPicture}
            isEditingTab={isEditingTab}
            isSaving={isSaving}
            isValidUname={isValidUname}
            checkUsernameMutationIsPending={checkUsernameMutation.isPending}
            years={years}
            setProjectToDelete={(type) => (id) => {
              const handlers: Record<string, (id: string) => void> = {
                project: setDeleteProject,
                sideProject: setDeleteSideProject,
                speaking: setDeleteSpeaking,
                work: setDeleteWork,
                education: setDeleteEducation,
                volunteering: setDeleteVolunteering,
                feature: setDeleteFeature,
                contact: setDeleteContact,
              };
              return handlers[type]?.(id);
            }}
            handlePictureUpload={handlePictureUpload}
            removePicture={handleAvatarRemove}
            onSave={handleGlobalSave}
            onDeleteAccount={handleDeleteAccount}
            setShowDeleteAccountWarning={setShowDeleteAccountWarning}
          />
        </DialogContent>
      </Dialog>

      {/* Dialogs */}
      <DeleteConfirmDialog
        open={!!pendingDelete}
        onOpenChange={(open) => !open && setPendingDelete(null)}
        description={
          pendingDelete ? DELETE_DESCRIPTIONS[pendingDelete.type] : ''
        }
        onConfirm={() => {
          if (pendingDelete) {
            DELETE_HANDLERS[pendingDelete.type](pendingDelete.id);
            setPendingDelete(null);
          }
        }}
        isLoading={isSaving}
      />

      <DeleteConfirmDialog
        open={showDeleteAccountWarning}
        onOpenChange={setShowDeleteAccountWarning}
        description="Are you absolutely sure? This will permanently delete your account, resume data, and username. This action cannot be undone."
        onConfirm={handleDeleteAccount}
        isLoading={isDeletingAccount}
        confirmLabel="Delete Account"
        loadingLabel="Deleting…"
      />

      <UnsavedChangesDialog
        open={showUnsavedWarning}
        onOpenChange={setShowUnsavedWarning}
        onLeaveAnyway={() => {
          setHasUnsavedChanges(false);
          setShowUnsavedWarning(false);
          setOpen(false);
          initResume(resume, username);
        }}
      />
    </>
  );
}

'use client';

import React, { useEffect, useRef } from 'react';
import { useResumeStore } from '@/store/useResumeStore';
import { Label } from '@/components/ui/label';
import { Input } from '@/components/ui/input';
import { Button } from '@/components/ui/button';
import dynamic from 'next/dynamic';
const RichTextEditor = dynamic(
  () =>
    import('@/components/composite/RichTextEditor').then(
      (mod) => mod.RichTextEditor,
    ),
  { ssr: false },
);
import { useUserActions } from '@/hooks/useUserActions';
import { Check, X } from 'lucide-react';

export function GeneralTab({
  initialUsername,
  localPicture,
  isUploadingPicture,
  handlePictureUpload,
  removePicture,
  onAvatarUpload,
}: {
  initialUsername: string;
  localPicture?: string;
  isUploadingPicture: boolean;
  handlePictureUpload: (
    e: React.ChangeEvent<HTMLInputElement>,
  ) => Promise<void>;
  removePicture: () => Promise<void>;
  onAvatarUpload?: () => void;
}) {
  const { resume, uname, setUname, updateHeader, updateResume } =
    useResumeStore();
  const { checkUsernameMutation } = useUserActions();
  const debounceTimerRef = useRef<NodeJS.Timeout | null>(null);

  const isInitialUsername = uname === initialUsername;

  useEffect(() => {
    if (!isInitialUsername && uname) {
      if (debounceTimerRef.current) clearTimeout(debounceTimerRef.current);
      debounceTimerRef.current = setTimeout(() => {
        checkUsernameMutation.mutateAsync(uname);
      }, 500);
    }
  }, [uname, isInitialUsername, checkUsernameMutation]);

  if (!resume) return null;

  const isValidUname =
    /^[a-zA-Z0-9-]+$/.test(uname) &&
    uname.length > 0 &&
    ((isInitialUsername || checkUsernameMutation.data?.available) ?? false);

  const { header, summary } = resume;

  return (
    <div className="mx-auto max-w-2xl space-y-8">
      {/* Avatar Section */}
      <div className="flex items-center gap-6">
        {/* Hidden file input — always present */}
        <input
          id="avatar-upload"
          type="file"
          accept="image/*"
          className="sr-only"
          onChange={(e) => {
            handlePictureUpload(e);
            e.target.value = '';
          }}
        />

        {localPicture ? (
          /* ── Has image: static avatar (not clickable) ── */
          <div className="relative size-20 shrink-0 overflow-hidden rounded-full">
            {isUploadingPicture && (
              <div className="absolute inset-0 z-10 flex items-center justify-center rounded-full bg-black/40">
                <svg
                  className="size-5 animate-spin text-white"
                  fill="none"
                  viewBox="0 0 24 24"
                >
                  <circle
                    className="opacity-25"
                    cx="12"
                    cy="12"
                    r="10"
                    stroke="currentColor"
                    strokeWidth="4"
                  />
                  <path
                    className="opacity-75"
                    fill="currentColor"
                    d="M4 12a8 8 0 018-8v8H4z"
                  />
                </svg>
              </div>
            )}
            <img
              width={300}
              height={300}
              src={localPicture}
              alt="Profile picture"
              className="size-full object-cover"
            />
          </div>
        ) : (
          /* ── No image: clickable camera placeholder ── */
          <label
            htmlFor="avatar-upload"
            className="group relative flex size-20 shrink-0 cursor-pointer items-center justify-center overflow-hidden rounded-full bg-gray-100"
          >
            {isUploadingPicture ? (
              <svg
                className="size-6 animate-spin text-gray-400"
                fill="none"
                viewBox="0 0 24 24"
              >
                <circle
                  className="opacity-25"
                  cx="12"
                  cy="12"
                  r="10"
                  stroke="currentColor"
                  strokeWidth="4"
                />
                <path
                  className="opacity-75"
                  fill="currentColor"
                  d="M4 12a8 8 0 018-8v8H4z"
                />
              </svg>
            ) : (
              <>
                <svg
                  xmlns="http://www.w3.org/2000/svg"
                  className="size-8 text-gray-400 transition-colors group-hover:text-gray-500"
                  fill="none"
                  viewBox="0 0 24 24"
                  stroke="currentColor"
                  strokeWidth={1.5}
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    d="M6.827 6.175A2.31 2.31 0 015.186 7.23c-.38.054-.757.112-1.134.175C2.999 7.58 2.25 8.507 2.25 9.574V18a2.25 2.25 0 002.25 2.25h15A2.25 2.25 0 0021.75 18V9.574c0-1.067-.75-1.994-1.802-2.169a47.865 47.865 0 00-1.134-.175 2.31 2.31 0 01-1.64-1.055l-.822-1.316a2.192 2.192 0 00-1.736-1.039 48.774 48.774 0 00-5.232 0 2.192 2.192 0 00-1.736 1.039l-.821 1.316z"
                  />
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    d="M16.5 12.75a4.5 4.5 0 11-9 0 4.5 4.5 0 019 0zM18.75 10.5h.008v.008h-.008V10.5z"
                  />
                </svg>
                {/* Subtle ring on hover */}
                <div className="absolute inset-0 rounded-full opacity-0 ring-2 ring-inset ring-gray-300 transition-opacity group-hover:opacity-100" />
              </>
            )}
          </label>
        )}

        {/* Action buttons */}
        <div className="flex flex-col gap-2">
          {localPicture ? (
            /* Image exists: show Upload (replace) + Remove */
            <>
              <Button
                variant="outline"
                size="sm"
                className="h-8 text-xs text-gray-600 transition-colors hover:border-red-200 hover:text-red-600"
                onClick={removePicture}
                disabled={isUploadingPicture}
              >
                Remove image
              </Button>
            </>
          ) : (
            /* No image: show Upload image */
            <>
              <Button
                variant="outline"
                size="sm"
                className="h-8 text-xs"
                onClick={() =>
                  document.getElementById('avatar-upload')?.click()
                }
                disabled={isUploadingPicture}
              >
                {isUploadingPicture ? 'Removing…' : 'Upload image'}
              </Button>
              <p className="text-[11px] leading-tight text-gray-400">
                JPG, PNG or GIF · max 5MB
              </p>
            </>
          )}
        </div>
      </div>

      <div className="space-y-6">
        <div className="space-y-2">
          <Label htmlFor="uname" className="text-xs text-gray-600">
            Username*
          </Label>
          <div className="relative flex items-center overflow-hidden rounded-md border border-gray-200 bg-white focus-within:ring-1 focus-within:ring-black">
            <span className="absolute left-3 top-1/2 z-10 -translate-y-1/2 select-none text-sm text-gray-400">
              portfoliofy.me/
            </span>
            <Input
              id="uname"
              placeholder="your-username"
              value={uname}
              onChange={(e) =>
                setUname(
                  e.target.value.toLowerCase().replace(/[^a-z0-9-]/g, ''),
                )
              }
              className="h-10 rounded-none border-none bg-transparent pl-[110px] shadow-none focus-visible:ring-0"
            />
            <div className="flex items-center pr-3">
              {isInitialUsername ? null : checkUsernameMutation.isPending ? (
                <div className="h-4 w-4 animate-spin rounded-full border-2 border-gray-300 border-t-black" />
              ) : isValidUname ? (
                <div className="absolute right-3 top-1/2 flex -translate-y-1/2 items-center justify-center rounded-full bg-green-500 p-0.5">
                  <Check className="h-3 w-3 text-white" strokeWidth={3} />
                </div>
              ) : (
                <div className="absolute right-3 top-1/2 flex -translate-y-1/2 items-center justify-center rounded-full bg-red-500 p-0.5">
                  <X className="h-3 w-3 text-white" strokeWidth={3} />
                </div>
              )}
            </div>
          </div>
        </div>

        <div className="space-y-2">
          <div className="flex justify-between">
            <Label htmlFor="displayName" className="text-xs text-gray-600">
              Display name*
            </Label>
            <span className="text-xs text-gray-400">
              {(header?.name || '').length} of 48
            </span>
          </div>
          <Input
            id="displayName"
            placeholder="The name on your profile"
            maxLength={48}
            value={header?.name || ''}
            onChange={(e) => updateHeader({ name: e.target.value })}
          />
        </div>

        <div className="space-y-2">
          <div className="flex justify-between">
            <Label htmlFor="shortAbout" className="text-xs text-gray-600">
              What do you do?
            </Label>
            <span className="text-xs text-gray-400">
              {(header?.shortAbout || '').length} of 32
            </span>
          </div>
          <Input
            id="shortAbout"
            placeholder="Architect, painter, etc"
            maxLength={32}
            value={header?.shortAbout || ''}
            onChange={(e) => updateHeader({ shortAbout: e.target.value })}
          />
        </div>

        <div className="space-y-2">
          <div className="flex justify-between">
            <Label htmlFor="location" className="text-xs text-gray-600">
              Location
            </Label>
            <span className="text-xs text-gray-400">
              {(header?.location || '').length} of 32
            </span>
          </div>
          <Input
            id="location"
            placeholder="Where you're based"
            maxLength={32}
            value={header?.location || ''}
            onChange={(e) => updateHeader({ location: e.target.value })}
          />
        </div>

        <div className="space-y-2">
          <div className="flex justify-between">
            <Label htmlFor="pronouns" className="text-xs text-gray-600">
              Pronouns
            </Label>
            <span className="text-xs text-gray-400">
              {(header?.pronouns || '').length} of 12
            </span>
          </div>
          <Input
            id="pronouns"
            placeholder="He/Him, etc"
            maxLength={12}
            value={header?.pronouns || ''}
            onChange={(e) => updateHeader({ pronouns: e.target.value })}
          />
        </div>

        <div className="space-y-2">
          <div className="flex justify-between">
            <Label htmlFor="website" className="text-xs text-gray-600">
              Website
            </Label>
            <span className="text-xs text-gray-400">
              {(header?.website || '').length} of 96
            </span>
          </div>
          <Input
            id="website"
            placeholder="https://example.com"
            maxLength={96}
            value={header?.website || ''}
            onChange={(e) => updateHeader({ website: e.target.value })}
          />
        </div>

        <div className="space-y-2 border-t border-gray-100 pt-4">
          <Label className="text-xs text-gray-600">About</Label>
          <RichTextEditor
            content={summary || ''}
            onChange={(val) => updateResume({ summary: val })}
          />
        </div>
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { toast } from 'sonner';
import { useResumeStore } from '@/store/useResumeStore';

export function PersonalDomainTab({ username }: { username: string }) {
  const { resume, updateDesign, setHasUnsavedChanges } = useResumeStore();

  const typography = resume?.design?.typography ?? 'sans';
  const theme = resume?.design?.theme ?? 'default';

  const [customDomain, setCustomDomain] = useState('');
  const [domainStatus, setDomainStatus] = useState<any>(null);
  const [isVerifyingDomain, setIsVerifyingDomain] = useState(false);

  const fetchDomain = async () => {
    setIsVerifyingDomain(true);
    try {
      const res = await fetch('/api/domain');
      const data = await res.json();
      if (data.domain) {
        setCustomDomain(data.domain);
        setDomainStatus(data.status === 'success' ? data.data : null);
      } else {
        setCustomDomain('');
        setDomainStatus(null);
      }
    } catch {}
    setIsVerifyingDomain(false);
  };

  useEffect(() => {
    fetchDomain();
  }, []);

  const handleDomainSave = async () => {
    if (!customDomain) return;
    setIsVerifyingDomain(true);
    try {
      const res = await fetch('/api/domain', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ domain: customDomain }),
      });
      const data = await res.json();
      if (data.error) {
        toast.error(data.error);
      } else {
        toast.success('Domain added successfully');
        fetchDomain();
      }
    } catch {
      toast.error('Failed to add domain');
    }
    setIsVerifyingDomain(false);
  };

  const handleDomainRemove = async () => {
    setIsVerifyingDomain(true);
    try {
      const res = await fetch('/api/domain', { method: 'DELETE' });
      if (res.ok) {
        toast.success('Domain removed');
        setCustomDomain('');
        setDomainStatus(null);
      }
    } catch {
      toast.error('Failed to remove domain');
    }
    setIsVerifyingDomain(false);
  };

  const siteLabel =
    domainStatus?.verified && customDomain
      ? customDomain
      : `portfoliofy.me/${username}`;

  const copyValue = (value: string) => {
    navigator.clipboard.writeText(value);
    toast.success('Copied to clipboard');
  };

  const dnsValue =
    domainStatus?.verification?.length > 0
      ? domainStatus.verification[0].value
      : '76.76.21.21';

  return (
    <div className="mx-auto flex h-full max-w-2xl flex-col">
      <div className="mb-8 flex items-center justify-between border-b border-gray-100 pb-4">
        <h2 className="text-2xl font-bold text-gray-900">Personal Domain</h2>
        <a
          href={
            domainStatus?.verified && customDomain
              ? `https://${customDomain}`
              : `https://portfoliofy.me/${username}`
          }
          target="_blank"
          rel="noopener noreferrer"
          className="inline-flex h-8 items-center justify-center rounded-md border border-gray-200 bg-white px-4 text-[13px] font-medium text-gray-900 shadow-sm transition-colors hover:bg-gray-50"
        >
          Visit site
        </a>
      </div>

      <div className="space-y-10">
        {/* Custom Domain */}
        <div className="space-y-6">
          <div className="flex flex-col gap-4">
            <div className="space-y-1">
              <h4 className="text-[14px] text-gray-900">Custom domain</h4>
              <p className="text-[13px] text-[#888888]">
                Optionally set a domain other than{' '}
                <a
                  href={`https://portfoliofy.me/${username}`}
                  className="text-gray-900 underline-offset-2 hover:underline"
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  portfoliofy.me/{username}
                </a>
              </p>
            </div>

            <div className="flex items-center gap-2">
              <div className="relative max-w-[320px] flex-1">
                {domainStatus?.verified ? (
                  <div className="absolute left-3 top-1/2 z-10 flex -translate-y-1/2 items-center justify-center">
                    <div className="rounded-full bg-[#7cb44d] p-[2px]">
                      <svg
                        className="h-[10px] w-[10px] text-white"
                        viewBox="0 0 24 24"
                        fill="none"
                        stroke="currentColor"
                        strokeWidth="3"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        aria-hidden="true"
                      >
                        <path d="M20 6L9 17l-5-5" />
                      </svg>
                    </div>
                  </div>
                ) : domainStatus ? (
                  <div className="absolute left-3 top-1/2 z-10 flex -translate-y-1/2 items-center justify-center">
                    <div className="flex h-[14px] w-[14px] items-center justify-center rounded-full bg-[#ebd955] text-[10px] font-bold text-white">
                      ?
                    </div>
                  </div>
                ) : null}
                <Input
                  value={customDomain}
                  onChange={(e) =>
                    setCustomDomain(e.target.value.toLowerCase())
                  }
                  placeholder="yourname.com…"
                  className={`h-9 w-full border-0 bg-[#f2f2f2] text-[13px] shadow-none focus-visible:ring-0 ${domainStatus ? 'pl-9 text-gray-700' : ''}`}
                  disabled={!!domainStatus}
                />
              </div>
              {!domainStatus ? (
                <Button
                  variant="outline"
                  size="sm"
                  className="h-8 rounded-md border border-gray-200 bg-white px-4 text-[13px] font-medium text-gray-900 shadow-sm transition-colors hover:bg-gray-50"
                  onClick={handleDomainSave}
                  disabled={isVerifyingDomain || !customDomain}
                >
                  {isVerifyingDomain ? 'Saving…' : 'Save'}
                </Button>
              ) : (
                <>
                  <Button
                    variant="outline"
                    size="sm"
                    className="h-9 rounded-lg border-gray-200 text-[13px] font-normal text-gray-400"
                    disabled
                  >
                    Save
                  </Button>
                  <Button
                    variant="outline"
                    size="sm"
                    className="h-9 rounded-lg border-gray-200 text-[13px] font-normal text-gray-500 hover:text-gray-900"
                    onClick={handleDomainRemove}
                    disabled={isVerifyingDomain}
                  >
                    Reset
                  </Button>
                </>
              )}
            </div>

            {domainStatus && (
              <>
                {domainStatus.verified ? (
                  <div className="relative mt-1 max-w-[400px]">
                    <div className="absolute -top-[6px] left-8 h-3 w-3 origin-center rotate-45 transform bg-[#e8eedd]" />
                    <div className="relative rounded-lg bg-[#e8eedd] px-4 py-2.5 text-[13px] text-[#6b8949]">
                      Your site is published at{' '}
                      <a
                        href={`https://${customDomain}`}
                        target="_blank"
                        rel="noopener noreferrer"
                        className="font-medium decoration-[#6b8949] underline-offset-2 hover:underline"
                      >
                        {customDomain}
                      </a>
                    </div>
                  </div>
                ) : (
                  <div className="relative mt-1 max-w-[500px]">
                    <div className="absolute -top-[6px] left-8 h-3 w-3 origin-center rotate-45 transform bg-[#f0eed9]" />
                    <div className="relative overflow-hidden rounded-xl bg-[#f0eed9] px-5 py-4">
                      <p className="mb-4 text-[13px] text-[#645c38]">
                        Set the following record on your DNS provider to
                        continue.
                      </p>

                      <div className="mb-1.5 grid grid-cols-4 gap-2 text-[13px] font-medium text-[#7d754b]">
                        <div>Type</div>
                        <div>Name</div>
                        <div className="col-span-2">Value</div>
                      </div>

                      <div className="grid grid-cols-4 items-center gap-2 text-[13px] text-[#4a4529]">
                        <div>
                          {domainStatus.verification?.length > 0
                            ? domainStatus.verification[0].type
                            : 'A'}
                        </div>
                        <div>
                          {domainStatus.verification?.length > 0
                            ? domainStatus.verification[0].domain
                            : '@'}
                        </div>
                        <div className="group col-span-2 flex items-center justify-between">
                          <div
                            className="cursor-pointer rounded bg-[#e4e0c7] px-1.5 py-0.5 selection:bg-transparent"
                            onClick={() => copyValue(dnsValue)}
                          >
                            {dnsValue}
                          </div>
                          <button
                            className="text-[12px] font-medium opacity-60 transition-opacity hover:opacity-100"
                            onClick={() => copyValue(dnsValue)}
                            aria-label="Copy DNS value"
                          >
                            Copy
                          </button>
                        </div>
                      </div>
                    </div>

                    <div className="mt-3 text-[12px] leading-relaxed text-[#a0a0a0]">
                      Please note that changing DNS settings can take several
                      minutes to take effect. If you've already updated your DNS
                      settings{' '}
                      <button
                        onClick={fetchDomain}
                        disabled={isVerifyingDomain}
                        className="font-medium text-gray-700 underline decoration-gray-300 underline-offset-2 hover:text-black disabled:opacity-50"
                      >
                        click here to manually refresh
                      </button>
                      , or visit this page for help.
                    </div>
                  </div>
                )}
              </>
            )}
          </div>
        </div>

        {/* Typography */}
        <div className="mt-4 space-y-4 border-t border-gray-100 pt-8">
          <div>
            <h4 className="text-[14px] text-gray-900">Typography</h4>
            <p className="mt-1 text-[13px] text-[#888888]">
              Change the typography shown on{' '}
              <span className="text-gray-900">{siteLabel}</span>
            </p>
          </div>

          <div className="flex flex-col gap-5">
            {(
              [
                {
                  value: 'sans',
                  label: 'Sans',
                  description:
                    'Graphik, designed by Christian Schwartz in 2009.',
                  fontClass: 'font-sans',
                },
                {
                  value: 'serif',
                  label: 'Serif',
                  description: 'Signifier, designed by Kris Sowersby in 2020.',
                  fontClass: 'font-serif',
                },
                {
                  value: 'mono',
                  label: 'Mono',
                  description: 'Diatype Mono, designed by Dinamo in 2020.',
                  fontClass: '',
                },
              ] as const
            ).map(({ value, label, description, fontClass }) => (
              <div
                key={value}
                className="group flex cursor-pointer items-center gap-4"
                onClick={() => {
                  updateDesign({ typography: value });
                  setHasUnsavedChanges(true);
                }}
              >
                <div
                  className={`flex h-[60px] w-[60px] shrink-0 items-center justify-center rounded-[16px] transition-colors ${
                    typography === value
                      ? 'border-[2.5px] border-[#3b82f6] bg-white'
                      : 'border border-gray-200 bg-white group-hover:border-gray-300'
                  }`}
                >
                  <span
                    className={`text-[22px] font-medium tracking-tight text-gray-900 ${fontClass}`}
                  >
                    Aa
                  </span>
                </div>
                <div className="flex flex-col gap-0.5">
                  <span className="text-[14px] font-medium text-gray-900">
                    {label}
                  </span>
                  <span className="text-[14px] text-[#737373]">
                    {description}
                  </span>
                </div>
              </div>
            ))}
          </div>
        </div>

        {/* Theme */}
        <div className="mt-4 space-y-4 border-t border-gray-100 pt-8">
          <div>
            <h4 className="text-[14px] text-gray-900">Theme</h4>
            <p className="mt-1 text-[13px] text-[#888888]">
              Change the theme shown on {siteLabel}
            </p>
          </div>

          <div className="flex flex-col gap-5 pt-2">
            {(
              [
                {
                  value: 'default',
                  label: 'Default',
                  description: 'Classic grayscale.',
                  bg: '#ffffff',
                  fg: '#111827',
                  border: '#e5e7eb',
                },
                {
                  value: 'brutalist',
                  label: 'Brutalist',
                  description: 'Raw internet materials.',
                  bg: '#b6b6b6',
                  fg: '#000000',
                  border: 'transparent',
                },
                {
                  value: 'swiss',
                  label: 'Swiss',
                  description: 'International typographic style.',
                  bg: '#e3583d',
                  fg: '#ffffff',
                  border: 'transparent',
                },
                {
                  value: 'klein',
                  label: 'Klein',
                  description: 'International Klein Blue.',
                  bg: '#1538a7',
                  fg: '#ffffff',
                  border: 'transparent',
                },
                {
                  value: 'red',
                  label: 'Red',
                  description: 'Radiates energy.',
                  bg: '#fcf4f0',
                  fg: '#ea5b4d',
                  border: 'transparent',
                },
                {
                  value: 'green',
                  label: 'Green',
                  description: 'Lush and leafy.',
                  bg: '#eff8eb',
                  fg: '#4fa847',
                  border: 'transparent',
                },
                {
                  value: 'blue',
                  label: 'Blue',
                  description: 'Da ba dee da ba di.',
                  bg: '#eaf3fa',
                  fg: '#267efb',
                  border: 'transparent',
                },
              ] as const
            ).map(({ value, label, description, bg, fg, border }) => (
              <div
                key={value}
                className="group flex cursor-pointer items-center gap-4"
