                  updateDesign({ theme: value });
                  setHasUnsavedChanges(true);
                }}
              >
                <div
                  className={`flex h-[60px] w-[60px] shrink-0 items-center justify-center rounded-[16px] transition-colors ${
                    theme === value
                      ? 'border-[2.5px] border-[#3b82f6]'
