          <div className="grid grid-cols-2 gap-6">
            <div className="space-y-2">
              <Label className="text-xs text-gray-600">Company*</Label>
              <Input
                value={currentWork.company}
                onChange={(e) =>
                  setCurrentWork({
                    ...currentWork,
                    company: e.target.value,
                  })
                }
                placeholder="Acme Design Studio"
              />
            </div>
            <div className="space-y-2">
              <Label className="text-xs text-gray-600">Position*</Label>
              <Input
                value={currentWork.title}
                onChange={(e) =>
                  setCurrentWork({
                    ...currentWork,
                    title: e.target.value,
                  })
                }
                placeholder="Senior Product Designer"
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-6">
            <div className="space-y-2">
              <Label className="text-xs text-gray-600">Start Date*</Label>
              <div className="flex gap-2">
                <Select
                  value={currentWork.startMonth || ''}
                  onValueChange={(val) =>
                    setCurrentWork({
                      ...currentWork,
                      startMonth: val,
                    })
                  }
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Month" />
                  </SelectTrigger>
                  <SelectContent>
                    {months.map((m) => (
                      <SelectItem key={m} value={m}>
                        {m}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
                <Select
                  value={currentWork.start || ''}
                  onValueChange={(val) =>
                    setCurrentWork({ ...currentWork, start: val })
                  }
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Year" />
                  </SelectTrigger>
                  <SelectContent>
                    {years.map((y) => (
                      <SelectItem key={y} value={y.toString()}>
                        {y}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>

            <div className="space-y-2">
              <Label className="text-xs text-gray-600">End Date*</Label>
              <div className="flex gap-2">
                {currentWork.end !== 'Present' && (
                  <Select
                    value={currentWork.endMonth || ''}
                    onValueChange={(val) =>
                      setCurrentWork({
                        ...currentWork,
                        endMonth: val,
                      })
                    }
                  >
                    <SelectTrigger>
                      <SelectValue placeholder="Month" />
                    </SelectTrigger>
                    <SelectContent>
                      {months.map((m) => (
                        <SelectItem key={m} value={m}>
                          {m}
                        </SelectItem>
                      ))}
                    </SelectContent>
                  </Select>
                )}
                <Select
                  value={currentWork.end || ''}
                  onValueChange={(val) =>
                    setCurrentWork({ ...currentWork, end: val })
                  }
                >
                  <SelectTrigger>
                    <SelectValue placeholder="Year" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="Present">Present</SelectItem>
                    {years.map((y) => (
                      <SelectItem key={y} value={y.toString()}>
                        {y}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>
          </div>

          <div className="grid grid-cols-2 gap-6">
            <div className="space-y-2">
              <Label className="text-xs text-gray-600">Location</Label>
              <Input
                value={currentWork.location || ''}
                onChange={(e) =>
                  setCurrentWork({
                    ...currentWork,
                    location: e.target.value,
                  })
                }
                placeholder="San Francisco, CA"
              />
            </div>
            <div className="space-y-2">
              <Label className="text-xs text-gray-600">Link</Label>
              <Input
                value={currentWork.link || ''}
                onChange={(e) =>
                  setCurrentWork({
                    ...currentWork,
                    link: e.target.value,
                  })
                }
                placeholder="https://example.com"
              />
            </div>
          </div>

          <div className="space-y-2 pt-2">
            <Label className="text-xs text-gray-600">Description</Label>
            <RichTextEditor
              content={currentWork.description || ''}
              onChange={(val) =>
                setCurrentWork({ ...currentWork, description: val })
              }
            />
          </div>

          <div className="absolute bottom-0 left-0 right-0 z-10 flex justify-end gap-3 border-t border-gray-100 bg-white p-4 md:px-8">
            <button
              onClick={() => setWorkView('list')}
              className="px-4 text-[14px] font-medium text-black hover:underline hover:underline-offset-2"
            >
              Cancel
            </button>
            <Button
              onClick={handleSave}
              disabled={!currentWork?.title || !currentWork?.company}
              variant="outline"
              className="h-9 rounded-md border border-gray-200 bg-white px-6 font-medium text-black shadow-sm"
            >
              Save
            </Button>
          </div>
        </div>
      )}
    </div>
  );
}

import { ImageResponse } from 'next/og';
import { NextRequest } from 'next/server';
import { getUserData } from '../utils';
import { readFileSync } from 'fs';
import { join } from 'path';

const graphikMedium = readFileSync(
  join(process.cwd(), 'public/fonts/Graphik-Medium.woff'),
);
const graphikRegular = readFileSync(
  join(process.cwd(), 'public/fonts/Graphik-Regular.woff'),
);

export async function GET(request: NextRequest) {
  try {
    const username = request.nextUrl.pathname.split('/')[1];

    const { user_id, resume, userProfile } = await getUserData(username);

    // Get data from resume
    const name = resume?.resumeData?.header?.name || username;
    const role = resume?.resumeData?.header?.shortAbout || '';
    const location = resume?.resumeData?.header?.location || '';

    let subtitle = role;
    if (role && location) {
      subtitle = `${role} in ${location}`;
    } else if (!role && location) {
      subtitle = `Based in ${location}`;
    }

    // Use profile image from Postgres users table
    const profileImageUrl =
      userProfile?.customImage ||
      userProfile?.image ||
      `${request.nextUrl.origin}/placeholder.svg`;

    // 40x40 subtle grid pattern
    const gridSvg = `data:image/svg+xml;base64,PHN2ZyB3aWR0aD0iNDAiIGhlaWdodD0iNDAiIHhtbG5zPSJodHRwOi8vd3d3LnczLm9yZy8yMDAwL3N2ZyI+PHBhdGggZD0iTTQwIDBIMHY0MGg0MFYweiIgZmlsbD0ibm9uZSIvPjxwYXRoIGQ9Ik0zOS41IDB2NDBNMCAzOS41aDQwIiBzdHJva2U9IiNlNWU1ZTUiIHN0cm9rZS13aWR0aD0iMSIvPjwvc3ZnPg==`;

    return new ImageResponse(
      <div
        style={{
          height: '100%',
          width: '100%',
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          justifyContent: 'center',
          backgroundColor: '#fafafa',
          position: 'relative',
        }}
      >
        {/* Grid Background */}
        <div
          style={{
            position: 'absolute',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            backgroundImage: `url(${gridSvg})`,
            backgroundSize: '40px 40px',
          }}
        />

        {/* Radial Gradient Overlay for focus */}
        <div
          style={{
            position: 'absolute',
            top: 0,
            left: 0,
            right: 0,
            bottom: 0,
            backgroundImage:
              'radial-gradient(circle at 50% 50%, rgba(250,250,250,1) 0%, rgba(250,250,250,0) 70%)',
          }}
        />

        {/* Content Wrapper */}
        <div
          style={{
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            zIndex: 10,
            padding: '0 40px',
          }}
        >
          {/* Circular Profile Image */}
          <img
            src={profileImageUrl}
            alt="Profile"
            style={{
              width: '180px',
              height: '180px',
              borderRadius: '90px',
              objectFit: 'cover',
              marginBottom: '40px',
              boxShadow: '0 8px 24px rgba(0,0,0,0.08)',
              border: '4px solid white',
            }}
          />

          {/* Title (Name) */}
          <div
            style={{
              fontFamily: 'Graphik-Medium',
              fontSize: '68px',
              fontWeight: 500,
              color: '#111111',
              marginBottom: '16px',
              textAlign: 'center',
              letterSpacing: '-0.02em',
            }}
          >
            {name}
          </div>

          {/* Subtitle (Role in Location) */}
          {subtitle && (
            <div
              style={{
                fontFamily: 'Graphik-Regular',
                fontSize: '36px',
                color: '#4a4a4a',
                textAlign: 'center',
                letterSpacing: '-0.01em',
              }}
            >
              {subtitle}
            </div>
          )}
        </div>
      </div>,
      {
        width: 1200,
        height: 630,
        fonts: [
          {
            name: 'Graphik-Medium',
            data: graphikMedium,
            weight: 500,
            style: 'normal',
          },
          {
            name: 'Graphik-Regular',
            data: graphikRegular,
            weight: 400,
            style: 'normal',
          },
        ],
      },
    );
  } catch (e: any) {
    console.error('OG Image Generation Error:', e);
    return new Response(`Failed to generate the image`, {
      status: 500,
    });
  }
}

import { useState } from 'react';
import { useRouter } from 'next/navigation';
import { ExploreSort, useExplore } from '@/hooks/useExplore';
import { X } from 'lucide-react';
import { motion } from 'framer-motion';

interface ExploreSidebarProps {
  onClose: () => void;
}

export function ExploreSidebar({ onClose }: ExploreSidebarProps) {
  const router = useRouter();
  const [query, setQuery] = useState('');
  const [sort, setSort] = useState<ExploreSort>('activity');

  const { data: users, isLoading } = useExplore(query, sort);

  const tabs: { id: ExploreSort; label: string }[] = [
    { id: 'activity', label: 'Activity' },
    { id: 'new', label: 'New' },
    { id: 'a-z', label: 'A–Z' },
  ];

  return (
    <div className="flex h-full w-full flex-col border-r border-[#E5E5E5] bg-white">
      <div className="mx-4 flex flex-col gap-4 border-b border-[#E5E5E5] pt-6">
        <div className="flex items-center gap-3">
          <div className="relative flex-1">
            <input
              type="text"
              placeholder="Explore people..."
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              className="w-full rounded-full bg-[#F2F2F2] px-4 py-2 text-[14px] text-gray-900 outline-none transition-all placeholder:text-gray-400"
            />
            {query && (
              <button
                onClick={() => setQuery('')}
                className="absolute right-3 top-1/2 -translate-y-1/2 rounded-full p-1 text-gray-400 transition-colors hover:bg-gray-200 hover:text-gray-700"
              >
                <X size={14} />
              </button>
            )}
          </div>
          <button
            onClick={onClose}
            className="text-[14px] text-black transition-colors hover:underline hover:underline-offset-2"
          >
            Done
          </button>
        </div>

        <div className="flex items-center gap-6">
          {tabs.map((tab) => (
            <button
              key={tab.id}
              onClick={() => setSort(tab.id)}
              className={`relative cursor-default pb-3 text-[13px] transition-all ${
                sort === tab.id ? 'text-black' : 'text-gray-400'
              }`}
            >
              {tab.label}
              {sort === tab.id && (
                <motion.div
                  layoutId="exploreTabIndicator"
                  className="absolute -bottom-[1px] left-0 right-0 h-[1px] bg-black"
                />
              )}
            </button>
          ))}
        </div>
      </div>

      <div className="flex-1 overflow-y-auto px-2 py-2">
        {isLoading ? (
          <div className="p-4 text-center text-[13px] text-gray-400">
            Loading...
          </div>
        ) : users?.length === 0 ? (
          <div className="p-4 text-center text-[13px] text-gray-400">
            No results found
          </div>
        ) : (
          <div className="flex flex-col">
            {users?.map((user) => (
              <button
                key={user.username}
                onClick={() => router.push(`/${user.username}`)}
                className="flex items-start gap-3 rounded-[10px] px-3 py-3 text-left transition-colors hover:bg-gray-200/50"
              >
                <div className="h-10 w-10 shrink-0 overflow-hidden rounded-full bg-gray-200">
                  {user.customImage || user.userImage ? (
                    <img
                      src={user.customImage || user.userImage!}
                      alt={user.name || user.username}
                      className="h-full w-full object-cover"
                    />
                  ) : (
                    <div className="flex h-full w-full items-center justify-center bg-gray-300 text-[14px] font-medium text-gray-600">
                      {(user.name || user.username).charAt(0).toUpperCase()}
                    </div>
                  )}
                </div>
                <div className="flex flex-col">
                  <span className="text-[14px] font-medium text-gray-900">
                    {user.name || user.username}
                  </span>
                  {user.shortAbout && (
                    <span className="mt-0.5 line-clamp-2 text-[13px] leading-tight text-gray-500">
                      {user.shortAbout}
                    </span>
                  )}
                </div>
              </button>
            ))}
          </div>
        )}
      </div>
    </div>
  );
}
